# Program ROM
routine $8000 reset                     ; power-on and reset: clear memory, set up the display, then idle
table $805a vram_lists_low 19
table $806d vram_lists_high 19
table $8080 vram_list_reset_offsets 2
routine $8082 frame_interrupt           ; once per frame: present the display updates, then run the game
routine $8182 handle_pause              ; start toggles pause while playing
value $8182 a mode
value $81b0 a state
value $81b9 a new_state
value $81c0 a new_state
label $81c2 store_pause_state ; keep the pause state as it is
routine $81c6 shuffle_sprite_slots      ; rotate OAM slots so that dropped sprites flicker instead of vanishing
result shuffle_sprite_slots x leftover_x ; where the slot loop leaves X (the game mode gets it)
scratch shuffle_sprite_slots $00 shuffle_limit ; the slot offset below which slots stay
value $81cd x index
value $81cf a old_offset
value $81da temp shuffled
value $81da a new_offset
value $81e0 a new_offset
value $81eb x next_pos
value $81f0 x next_pos
value $81f7 y group
value $81f9 a first_offset
value $8200 a second_offset
routine $8212 run_game_mode             ; dispatch on the game mode (title, playing, victory, game over)
param run_game_mode x leftover_x ; the X the frame interrupt leaves: 7, or the sprite shuffler's
value $8212 a mode
table $8218 game_mode_tasks 8
routine $8220 hide_all_sprites          ; move every sprite below the screen
routine $8223 hide_sprites_but_zero     ; move every sprite but sprite 0 (the status bar split) below the screen
routine $8225 hide_sprites_from         ; move the sprites from Y's OAM offset to the end below the screen
param hide_sprites_from y oam_offset ; the first sprite's offset in the OAM copy
result hide_sprites_from y oam_offset ; 0, past the last sprite
routine $8231 title_mode                ; dispatch on the title's task: screen setup, title menu, new game
param title_mode x leftover_x ; the X the frame interrupt leaves
value $8231 a task
table $8237 title_mode_tasks 8
table $823f world_select_template 6
routine $8245 title_menu                ; title screen input: start, world select, demo
value $8245 y choose_world
value $8275 y choose_world
value $824a a buttons
value $8303 x digit
label $82d8 start_pressed ; start begins the game
label $82c9 restart_title ; the demo is over: back to the title
label $82c0 run_title_frame ; run a frame of the attract mode
label $82bb no_world_select ; world select is locked
routine $830e start_continue            ; continue from the world in A, at its first area
param start_continue a world ; the world to continue from
result start_continue x leftover_x ; 0, where its loop leaves X
table $831d player_select_icon_data 8
routine $8325 draw_player_select_icon   ; queue the title's mushroom cursor at the selected player count
value $8325 y index
table $8340 demo_buttons 21
table $8355 demo_durations 22
routine $836b play_demo                 ; feed recorded buttons to the player in attract mode
result play_demo carry demo_over ; the recording has ended
value $836b x action
value $8378 a duration
routine $838b victory_mode              ; run the victory task, and the remaining objects once the bridge is down
param victory_mode x leftover_x ; the X the frame interrupt leaves
value $8393 x first_slot
routine $83a0 run_victory_task          ; dispatch on the victory task: collapse the bridge, walk, messages, next world
param run_victory_task x leftover_x ; the X the frame interrupt leaves
value $83a0 a task
table $83a6 victory_tasks 10
routine $83b0 start_victory             ; aim the walk at the next page and start the victory music
routine $83bd victory_walk              ; walk the player right and scroll until the page past the bridge
param victory_walk x leftover_x ; the X the frame interrupt leaves
value $83bd y walk_right
value $83cf y walk_right
value $83df temp scroll_sum
label $83d0 drive_victory_walk ; walk the player on
routine $83f6 show_victory_messages     ; queue the thank-you messages one by one, then set the end timer
value $83fb a step
